arguments.file_text:
@namespace sv_47e34cd0186445749d1ac2e0aee618e1.Components.Pages.Apply

<h4>Personal Information</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="mb-3">
    <label class="form-label">Full Name *</label>
    <input type="text" class="form-control" value="@Model.FullName"
           @onchange="e => Model = Model with { FullName = (string?)e.Value ?? "" }" />
</div>

<div class="mb-3">
    <label class="form-label">Email *</label>
    <input type="email" class="form-control" value="@Model.Email"
           @onchange="e => Model = Model with { Email = (string?)e.Value ?? "" }" />
    @if (IsValidatingEmail)
    {
        <small class="text-muted">Validating email...</small>
    }
</div>

<div class="mb-3">
    <label class="form-label">Phone *</label>
    <input type="tel" class="form-control" value="@Model.Phone"
           @onchange="e => Model = Model with { Phone = (string?)e.Value ?? "" }" />
</div>

<div class="mb-3">
    <label class="form-label">Address *</label>
    <textarea class="form-control" rows="2" value="@Model.Address"
              @onchange="e => Model = Model with { Address = (string?)e.Value ?? "" }"></textarea>
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidatingEmail">
        @if (IsValidatingEmail)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter] public PersonalInfo Model { get; set; } = new("", "", "", "");
    [Parameter] public EventCallback<PersonalInfo> ModelChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ErrorMessage;
    private bool IsValidatingEmail;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        if (ValidateEmail != null)
        {
            IsValidatingEmail = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Model.Email);
            IsValidatingEmail = false;

            if (!isValid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }
        }

        await ModelChanged.InvokeAsync(Model);
        await OnNext.InvokeAsync();
    }
}

@namespace sv_47e34cd0186445749d1ac2e0aee618e1.Components.Pages.Apply

<h4>Work History</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <WorkEntryForm Entry="@Entries[index]"
                   Index="index"
                   ShowRemove="@(Entries.Count > 1)"
                   OnEntryChanged="e => UpdateEntry(index, e)"
                   OnRemove="() => RemoveEntry(index)" />
}

<button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<WorkEntry> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntry>> EntriesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void UpdateEntry(int index, WorkEntry updated)
    {
        Entries[index] = updated;
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position must have a company name and job title.";
                return;
            }
        }

        await EntriesChanged.InvokeAsync(Entries);
        await OnNext.InvokeAsync();
    }
}

@namespace sv_47e34cd0186445749d1ac2e0aee618e1.Components.Pages.Apply

<h4>References</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    <ReferenceForm Reference="@References[index]"
                   Index="index"
                   ShowRemove="@(References.Count > 1)"
                   OnReferenceChanged="r => UpdateReference(index, r)"
                   OnRemove="() => RemoveReference(index)" />
}

@if (References.Count < 3)
{
    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public EventCallback<List<Reference>> ReferencesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void UpdateReference(int index, Reference updated)
    {
        References[index] = updated;
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference("", "", "", ""));
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 1)
        {
