@namespace sv_47e34cd0186445749d1ac2e0aee618e1.Components.Pages.ApplicationSteps

<h4>Personal Information</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="mb-3">
    <label class="form-label">Full Name *</label>
    <input type="text" class="form-control" @bind="fullName" @bind:event="onchange" />
</div>

<div class="mb-3">
    <label class="form-label">Email *</label>
    <input type="email" class="form-control" @bind="email" @bind:event="onchange" />
    @if (IsValidatingEmail)
    {
        <small class="text-muted">Validating email...</small>
    }
</div>

<div class="mb-3">
    <label class="form-label">Phone *</label>
    <input type="tel" class="form-control" @bind="phone" @bind:event="onchange" />
</div>

<div class="mb-3">
    <label class="form-label">Address *</label>
    <textarea class="form-control" rows="2" @bind="address" @bind:event="onchange"></textarea>
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidatingEmail">
        @if (IsValidatingEmail)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter] public PersonalInfo Model { get; set; } = new("", "", "", "");
    [Parameter] public EventCallback<PersonalInfo> ModelChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";
    private string? ErrorMessage;
    private bool IsValidatingEmail;

    protected override void OnParametersSet()
    {
        fullName = Model.FullName;
        email = Model.Email;
        phone = Model.Phone;
        address = Model.Address;
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        Model = new PersonalInfo(fullName, email, phone, address);

        if (string.IsNullOrWhiteSpace(fullName) ||
            string.IsNullOrWhiteSpace(email) ||
            string.IsNullOrWhiteSpace(phone) ||
            string.IsNullOrWhiteSpace(address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        if (ValidateEmail != null)
        {
            IsValidatingEmail = true;
            StateHasChanged();

            var isValid = await ValidateEmail(email);
            IsValidatingEmail = false;

            if (!isValid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }
        }

        await ModelChanged.InvokeAsync(Model);
        await OnNext.InvokeAsync();
    }
}
EOF

